import{_ as t,o as e,c as s,a2 as r}from"./chunks/framework.DajbkT6K.js";const g=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),o={name:"guide/faq.md"};function n(i,a,l,h,d,p){return e(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>遇到问题，第一步永远是<strong>把情况告诉人格</strong>：报错原文、你做了什么、期望是什么。它能看到很多你看不到的东西，多数问题它自己就能查清楚。</p><h2 id="安装和启动" tabindex="-1">安装和启动 <a class="header-anchor" href="#安装和启动" aria-label="Permalink to &quot;安装和启动&quot;">​</a></h2><p><strong>Mac 提示「已损坏，无法打开」或「无法验证开发者」</strong> 安装包没有做苹果的付费签名。打开「终端」执行下面这行，再打开即可：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/全能管家.app</span></span></code></pre></div><p><strong>Windows 提示「Windows 已保护你的电脑」</strong> 点「更多信息」→「仍要运行」。</p><h2 id="人格不说话" tabindex="-1">人格不说话 <a class="header-anchor" href="#人格不说话" aria-label="Permalink to &quot;人格不说话&quot;">​</a></h2><p><strong>「还没选模型，暂时无法回复」</strong> 人格管理 → 这个人格 →「AI」页，选一个模型。</p><p><strong>报 401、key 不对</strong> 系统设置 →「模型服务」→「API 凭据」，那一条点「测试」。不通就重新复制粘贴 Key，注意前后别带空格。用订阅的，看「Claude 订阅」那里是不是还显示「已开启并登录」。</p><p><strong>报 400，时好时坏</strong> 多半是网关或服务商临时拒收，过一会儿再发。一直这样，换一条线路，或者把报错原文发给人格。</p><p><strong>改了设置没生效</strong> 接入方式、模型、搜索这类设置，改完要重新打开那个人格。</p><h2 id="记忆" tabindex="-1">记忆 <a class="header-anchor" href="#记忆" aria-label="Permalink to &quot;记忆&quot;">​</a></h2><p><strong>它不记得刚才说的话</strong> 聊得太长时人格会整理上下文，重新开始一段对话，聊天原话不会全部带过去，但要紧的事它已经记进了记忆。想让它记住的，明说「记住：……」。</p><p><strong>它记错了</strong> 直接纠正：「不对，应该是……」。它会改掉旧的那条。</p><h2 id="通道" tabindex="-1">通道 <a class="header-anchor" href="#通道" aria-label="Permalink to &quot;通道&quot;">​</a></h2><p><strong>机器人收不到消息</strong> 人格要开着；看卡片是不是「运行中」。飞书、钉钉改了权限或事件后要重新发布版本；Discord 要打开「Message Content Intent」。详见 <a href="/aibutler/docs/guide/channels.html">通道</a>。</p><h2 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to &quot;搜索&quot;">​</a></h2><p><strong>搜不到东西</strong> 看 <a href="/aibutler/docs/guide/search.html">联网搜索</a>。在中国大陆，加一个 Bing 通常就能解决。</p><h2 id="数据在哪" tabindex="-1">数据在哪 <a class="header-anchor" href="#数据在哪" aria-label="Permalink to &quot;数据在哪&quot;">​</a></h2><p>所有数据都在你自己的电脑上。Mac 默认在 <code>~/Library/Application Support/butler</code>，Windows 默认在 <code>%APPDATA%\\butler</code>。每个人格的资料在建人格时选的目录里。</p>',20)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
